1	package api
2	
3	// These regression cases exercise the storage-agnostic assembly entry
4	// NewRouterWithStore: the router is built from a caller-supplied
5	// service.Store — no Ping method, no SQLite, no database/sql — plus an
6	// independently provided health check. They pin the published behavior of
7	// POST/GET /v1/artifacts and GET /healthz on that boundary, including error
8	// priority and the mutual independence of the health check and the store.
9	
10	import (
11		"errors"
12		"net/http"
13		"net/http/httptest"
14		"path/filepath"
15		"testing"
16	
17		"github.com/gin-gonic/gin"
18	
19		"github.com/Bob-xisuke/orb-registry-catalog/internal/service"
20		"github.com/Bob-xisuke/orb-registry-catalog/internal/store"
21	)
22	
23	// testDigestC is a third valid digest for cross-entry scenarios; testDigestA
24	// and testDigestB come from artifacts_test.go.
25	const testDigestC = "sha256:" + "cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc"
26	
27	// assemblyStore is a caller-supplied service.Store written only against the
28	// exported storage contract. It keeps records in memory, can be forced to
29	// fail like any backend, and counts calls so tests can prove that rejected
30	// input never reaches storage.
31	type assemblyStore struct {
32		records []service.Record
33		byID    map[string]int               // repository\x00digest -> records index
34		tags    map[string]map[string]string // repository -> tag -> digest
35		fault   error
36		calls   map[string]int
37	}
38	
39	func newAssemblyStore() *assemblyStore {
40		return &assemblyStore{
41			byID:  make(map[string]int),
42			tags:  make(map[string]map[string]string),
43			calls: make(map[string]int),
44		}
45	}
46	
47	func assemblyID(repository, digest string) string { return repository + "\x00" + digest }
48	
49	func (a *assemblyStore) Register(in service.Record) (service.Record, service.RegisterStatus, error) {
50		a.calls["register"]++
51		if a.fault != nil {
52			return service.Record{}, 0, a.fault
53		}
54		key := assemblyID(in.Repository, in.Digest)
55		if idx, ok := a.byID[key]; ok {
56			existing := a.records[idx]
57			if existing.Tag == in.Tag &&
58				existing.SignatureVerified == in.SignatureVerified &&
59				existing.RetentionDays == in.RetentionDays &&
60				existing.SizeBytes == in.SizeBytes {
61				return existing, service.StatusDuplicate, nil
62			}
63			return service.Record{}, service.StatusConflict, nil
64		}
65		a.byID[key] = len(a.records)
66		a.records = append(a.records, in)
67		if a.tags[in.Repository] == nil {
68			a.tags[in.Repository] = make(map[string]string)
69		}
70		a.tags[in.Repository][in.Tag] = in.Digest
71		return in, service.StatusCreated, nil
72	}
73	
74	func (a *assemblyStore) ListRecords(repository string) ([]service.Record, error) {
75		a.calls["list"]++
76		if a.fault != nil {
77			return nil, a.fault
78		}
79		var out []service.Record
80		for _, record := range a.records {
81			if record.Repository == repository {
82				out = append(out, record)
83			}
84		}
85		return out, nil
86	}
87	
88	func (a *assemblyStore) RecordByDigest(repository, digest string) (service.Record, error) {
89		a.calls["digest"]++
90		if a.fault != nil {
91			return service.Record{}, a.fault
92		}
93		if idx, ok := a.byID[assemblyID(repository, digest)]; ok {
94			return a.records[idx], nil
95		}
96		return service.Record{}, service.ErrRecordNotFound
97	}
98	
99	func (a *assemblyStore) RecordByTag(repository, tag string) (service.Record, error) {
100		a.calls["tag"]++
101		if a.fault != nil {
102			return service.Record{}, a.fault
103		}
104		digest, ok := a.tags[repository][tag]
105		if !ok {
106			return service.Record{}, service.ErrRecordNotFound
107		}
108		return a.records[a.byID[assemblyID(repository, digest)]], nil
109	}
110	
111	func (a *assemblyStore) totalCalls() int {
112		total := 0
113		for _, n := range a.calls {
114			total += n
115		}
116		return total
117	}
118	
119	// assemblyProbe is a health check the test flips between requests; every
120	// /healthz call must consult it again.
121	type assemblyProbe struct {
122		err   error
123		calls int
124	}
125	
126	func (p *assemblyProbe) check() error {
127		p.calls++
128		return p.err
129	}
130	
131	func newAssemblyRouter(st *assemblyStore, probe *assemblyProbe) *gin.Engine {
132		return NewRouterWithStore(st, probe.check)
133	}
134	
135	func getHealth(t *testing.T, router *gin.Engine) *httptest.ResponseRecorder {
136		t.Helper()
137		recorder := httptest.NewRecorder()
138		router.ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, "/healthz", nil))
139		return recorder
140	}
141	
142	// TestAssemblyEntryRegisterAndQuery walks the full registration and query
143	// contract through the new entry on a caller-supplied store: first
144	// registration and identical retry share 201 and the original pushed_at, the
145	// tag pointer moves only on new content, conflicts are 409, lists keep
146	// first-registration order and misses are 404.
147	func TestAssemblyEntryRegisterAndQuery(t *testing.T) {
148		st := newAssemblyStore()
149		router := newAssemblyRouter(st, &assemblyProbe{})
150	
151		bodyA := registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)
152		bodyB := registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB)
153	
154		first := postArtifact(t, router, bodyA)
155		if first.Code != http.StatusCreated {
156			t.Fatalf("register A status = %d, want %d (%s)", first.Code, http.StatusCreated, first.Body)
157		}
158		pushedA, _ := decodeBody(t, first)["pushed_at"].(string)
159		if pushedA == "" {
160			t.Fatalf("A response has no pushed_at: %s", first.Body)
161		}
162	
163		second := postArtifact(t, router, bodyB)
164		if second.Code != http.StatusCreated {
165			t.Fatalf("register B status = %d, want %d (%s)", second.Code, http.StatusCreated, second.Body)
166		}
167		pushedB, _ := decodeBody(t, second)["pushed_at"].(string)
168	
169		// The tag pointer moved to B; A survives by digest.
170		if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestB {
171			t.Fatalf("tag after B points at %v, want %s", got["digest"], testDigestB)
172		}
173		expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestA)),
174			sequenceRepo, testDigestA, sequenceTag, true,
175			float64(regRetention), float64(regSizeA), pushedA)
176	
177		// Identical retry of A: 201 with the original pushed_at, no new record and
178		// the tag pointer does not move back.
179		retry := postArtifact(t, router, bodyA)
180		if retry.Code != http.StatusCreated {
181			t.Fatalf("retry A status = %d, want %d (%s)", retry.Code, http.StatusCreated, retry.Body)
182		}
183		if got := decodeBody(t, retry)["pushed_at"]; got != pushedA {
184			t.Fatalf("retry pushed_at = %v, want original %v", got, pushedA)
185		}
186		if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestB {
187			t.Fatalf("retry moved the tag pointer: %v", got)
188		}
189		if digests := recordDigests(allRecords(t, queryList(t, router, sequenceRepo))); len(digests) != 2 ||
190			digests[0] != testDigestA || digests[1] != testDigestB {
191			t.Fatalf("list = %v, want [%s %s] in registration order", digests, testDigestA, testDigestB)
192		}
193	
194		// Same identity with different content: 409, and nothing changes.
195		conflict := postArtifact(t, router,
196			registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeB))
197		assertErrorResponse(t, conflict, http.StatusConflict, codeConflict, msgConflict)
198		expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestA)),
199			sequenceRepo, testDigestA, sequenceTag, true,
200			float64(regRetention), float64(regSizeA), pushedA)
201		if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["pushed_at"] != pushedB {
202			t.Fatalf("tagged record changed after conflict: %v", got)
203		}
204	
205		// Legal queries with no match are 404.
206		assertErrorResponse(t, queryList(t, router, "registry-demo/missing"),
207			http.StatusNotFound, codeNotFound, msgNotFound)
208		assertErrorResponse(t, queryByTag(t, router, sequenceRepo, "missing-tag"),
209			http.StatusNotFound, codeNotFound, msgNotFound)
210		assertErrorResponse(t, queryByDigest(t, router, sequenceRepo, testDigestB[:len(testDigestB)-1]+"c"),
211			http.StatusNotFound, codeNotFound, msgNotFound)
212	}
213	
214	// TestAssemblyEntryErrorPriority pins the error ordering on the new entry:
215	// invalid input is a 400 decided before any storage call — even while the
216	// store is down — and a legal request that hits a failing store is a 503.
217	func TestAssemblyEntryErrorPriority(t *testing.T) {
218		st := newAssemblyStore()
219		router := newAssemblyRouter(st, &assemblyProbe{})
220	
221		// Invalid registration and query bodies are rejected without touching the
222		// store, while it is still healthy.
223		assertErrorResponse(t, postArtifact(t, router, `{"repository":`),
224			http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
225		assertErrorResponse(t, postArtifact(t, router, registrationWithField("size_bytes", "null")),
226			http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
227		assertErrorResponse(t, getArtifacts(t, router, "tag="+sequenceTag),
228			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
229		assertErrorResponse(t, getArtifacts(t, router, "repository="+sequenceRepo+"&tag=&digest="),
230			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
231		if got := st.totalCalls(); got != 0 {
232			t.Fatalf("invalid input reached the store %d times, want 0", got)
233		}
234	
235		// With the store faulted, invalid input still wins its 400 over the 503.
236		st.fault = errors.New("assembly backend down")
237		assertErrorResponse(t, postArtifact(t, router, registrationWithField("signature_verified", "null")),
238			http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
239		assertErrorResponse(t, getArtifacts(t, router, "repository="+sequenceRepo+"&digest=sha256:xyz"),
240			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
241	
242		// Legal requests degrade to 503 storage_unavailable on the same faulted
243		// store, register and query alike.
244		assertErrorResponse(t, postArtifact(t, router,
245			registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)),
246			http.StatusServiceUnavailable, codeStorage, msgStorage)
247		assertErrorResponse(t, queryList(t, router, sequenceRepo),
248			http.StatusServiceUnavailable, codeStorage, msgStorage)
249		assertErrorResponse(t, queryByTag(t, router, sequenceRepo, sequenceTag),
250			http.StatusServiceUnavailable, codeStorage, msgStorage)
251		assertErrorResponse(t, queryByDigest(t, router, sequenceRepo, testDigestA),
252			http.StatusServiceUnavailable, codeStorage, msgStorage)
253	}
254	
255	// TestAssemblyHealthCheckIndependent proves the health check and the store
256	// answer for themselves alone: a failing probe degrades only /healthz, a
257	// failing store degrades only the artifact entries, and /healthz reflects the
258	// probe result on every single call.
259	func TestAssemblyHealthCheckIndependent(t *testing.T) {
260		st := newAssemblyStore()
261		probe := &assemblyProbe{}
262		router := newAssemblyRouter(st, probe)
263	
264		bodyA := registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)
265	
266		// Healthy probe: the published 200 body.
267		recorder := getHealth(t, router)
268		if recorder.Code != http.StatusOK || recorder.Body.String() != `{"database":"ok","status":"ok"}` {
269			t.Fatalf("healthy /healthz = %d %s", recorder.Code, recorder.Body)
270		}
271	
272		// Failing probe: /healthz is 503 with the published shape, but
273		// registration and queries are not gated on the probe and still succeed.
274		probe.err = errors.New("probe: dependency unreachable")
275		assertErrorResponse(t, getHealth(t, router),
276			http.StatusServiceUnavailable, codeStorage, msgStorage)
277		if got := postArtifact(t, router, bodyA); got.Code != http.StatusCreated {
278			t.Fatalf("register with failing probe status = %d (%s)", got.Code, got.Body)
279		}
280		if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestA {
281			t.Fatalf("query with failing probe = %v, want the registered record", got)
282		}
283	
284		// The probe is consulted on every call: clearing the fault restores 200.
285		probe.err = nil
286		if recorder := getHealth(t, router); recorder.Code != http.StatusOK {
287			t.Fatalf("/healthz after probe recovery = %d, want %d", recorder.Code, http.StatusOK)
288		}
289		if probe.calls != 3 {
290			t.Fatalf("probe consulted %d times for 3 /healthz calls", probe.calls)
291		}
292	
293		// A failing store does not stand in for the health check: /healthz stays
294		// 200 on the healthy probe while legal artifact requests are 503.
295		st.fault = errors.New("assembly backend down")
296		if recorder := getHealth(t, router); recorder.Code != http.StatusOK {
297			t.Fatalf("/healthz with failing store = %d, want %d", recorder.Code, http.StatusOK)
298		}
299		assertErrorResponse(t, postArtifact(t, router,
300			registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB)),
301			http.StatusServiceUnavailable, codeStorage, msgStorage)
302		assertErrorResponse(t, queryList(t, router, sequenceRepo),
303			http.StatusServiceUnavailable, codeStorage, msgStorage)
304	}
305	
306	// TestAssemblyEntryUnknownRoute keeps the published 404 shape on the new
307	// entry, independent of store and probe state.
308	func TestAssemblyEntryUnknownRoute(t *testing.T) {
309		router := newAssemblyRouter(newAssemblyStore(), &assemblyProbe{})
310	
311		recorder := httptest.NewRecorder()
312		router.ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, "/missing", nil))
313		assertErrorResponse(t, recorder, http.StatusNotFound, "route_not_found", "no route matches this path")
314	}
315	
316	// TestSQLiteEntryStaysCompatibleWithExistingData writes records through the
317	// original NewRouter assembly, reopens the same database file behind the new
318	// NewRouterWithStore entry and confirms the committed data — push times, list
319	// order, unique identity and the current tag pointer — reads back unchanged,
320	// and that the new entry keeps registering into the same store.
321	func TestSQLiteEntryStaysCompatibleWithExistingData(t *testing.T) {
322		path := filepath.Join(t.TempDir(), "service.db")
323	
324		st, err := store.Open(path)
325		if err != nil {
326			t.Fatalf("open: %v", err)
327		}
328		legacy := NewRouter(st)
329		first := postArtifact(t, legacy, registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA))
330		if first.Code != http.StatusCreated {
331			t.Fatalf("legacy register A status = %d (%s)", first.Code, first.Body)
332		}
333		pushedA := decodeBody(t, first)["pushed_at"].(string)
334		second := postArtifact(t, legacy, registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB))
335		if second.Code != http.StatusCreated {
336			t.Fatalf("legacy register B status = %d (%s)", second.Code, second.Body)
337		}
338		pushedB := decodeBody(t, second)["pushed_at"].(string)
339		if err := st.Close(); err != nil {
340			t.Fatalf("close before reopen: %v", err)
341		}
342	
343		// Reopen the same file behind the new entry; the store's Ping is passed
344		// explicitly as the health check, like NewRouter does.
345		reopened, err := store.Open(path)
346		if err != nil {
347			t.Fatalf("reopen: %v", err)
348		}
349		t.Cleanup(func() { reopened.Close() })
350		router := NewRouterWithStore(reopened, reopened.Ping)
351	
352		// Existing data survives: order, push times and the tag pointer.
353		records := allRecords(t, queryList(t, router, sequenceRepo))
354		if digests := recordDigests(records); len(digests) != 2 ||
355			digests[0] != testDigestA || digests[1] != testDigestB {
356			t.Fatalf("list after reopen = %v, want A then B", digests)
357		}
358		if records[0].(map[string]any)["pushed_at"] != pushedA ||
359			records[1].(map[string]any)["pushed_at"] != pushedB {
360			t.Fatalf("pushed_at values did not survive reopen: %v", records)
361		}
362		tagged := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag))
363		if tagged["digest"] != testDigestB || tagged["pushed_at"] != pushedB {
364			t.Fatalf("tag pointer did not survive reopen: %v", tagged)
365		}
366	
367		// The unique identity still holds across the boundary: a verbatim retry of
368		// A through the new entry is a duplicate, not a new record.
369		retry := postArtifact(t, router, registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA))
370		if retry.Code != http.StatusCreated {
371			t.Fatalf("retry A status = %d (%s)", retry.Code, retry.Body)
372		}
373		if got := decodeBody(t, retry)["pushed_at"]; got != pushedA {
374			t.Fatalf("retry pushed_at = %v, want original %v", got, pushedA)
375		}
376		if digests := recordDigests(allRecords(t, queryList(t, router, sequenceRepo))); len(digests) != 2 {
377			t.Fatalf("retry added a record across the boundary: %v", digests)
378		}
379	
380		// New registrations through the new entry land in the same store and are
381		// visible to a fresh legacy router on the same file.
382		third := postArtifact(t, router,
383			registration(sequenceRepo, testDigestC, sequenceTag, true, regRetention, regSizeB))
384		if third.Code != http.StatusCreated {
385			t.Fatalf("register C status = %d (%s)", third.Code, third.Body)
386		}
387		pushedC := decodeBody(t, third)["pushed_at"].(string)
388		if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestC {
389			t.Fatalf("tag after C points at %v, want %s", got["digest"], testDigestC)
390		}
391		if err := reopened.Close(); err != nil {
392			t.Fatalf("close before legacy reopen: %v", err)
393		}
394	
395		legacyStore, err := store.Open(path)
396		if err != nil {
397			t.Fatalf("legacy reopen: %v", err)
398		}
399		t.Cleanup(func() { legacyStore.Close() })
400		legacy = NewRouter(legacyStore)
401		records = allRecords(t, queryList(t, legacy, sequenceRepo))
402		if digests := recordDigests(records); len(digests) != 3 ||
403			digests[0] != testDigestA || digests[1] != testDigestB || digests[2] != testDigestC {
404			t.Fatalf("legacy list after cross-entry writes = %v, want A B C", digests)
405		}
406		expectStoredRecord(t, soleRecord(t, queryByTag(t, legacy, sequenceRepo, sequenceTag)),
407			sequenceRepo, testDigestC, sequenceTag, true,
408			float64(regRetention), float64(regSizeB), pushedC)
409	}
